v class="value">${num(d.reposiciones)}</div><div class="meta">disponibles</div></div><div class="card"><div class="label">Avisos hoy</div><div class="value">${num(d.avisos_hoy)}</div></div><div class="card"><div class="label">Pendientes</div><div class="value">${num(d.pendientes)}</div></div></div><section class="section"><div class="section-head"><h2>Acciones rápidas</h2><span>Lo más usado</span></div><div class="quick"><a href="/sesiones.php" class="primary">Tomar asistencia</a><a href="/pagos.php">Registrar pago</a><a href="/alertas.php">Ver alertas</a><a href="/alumnos.php">Ver alumnos</a><a href="/ausencias.php">Ausencias</a></div></section><section class="section"><div class="section-head"><h2>Ocupación por horario</h2><span>${horarios.length} horarios con alumnos</span></div><div class="panel"><div class="schedule">${horarios.length?horarios.map(x=>`<div class="slot"><strong>${esc(String(x.hora_inicio??'').slice(0,5))}–${esc(String(x.hora_fin??'').slice(0,5))}</strong><span>${num(x.alumnos)} alumno${num(x.alumnos)===1?'':'s'}</span></div>`).join(''):'<div class="empty">Sin alumnos asignados.</div>'}</div></div></section>`}catch(e){c.innerHTML=`<div class="empty error">${esc(e.message||'No se pudo cargar el dashboard')}</div>`}}cargar();
